1	import Foundation
2	import libgit2
3	
4	/// Reachability reads against a git repo's `origin` refs, straight on libgit2's C API (one of only
5	/// three readers that do — `GitCommitDiff` does rename-detected commit diffs and `GitDiffStats` the
6	/// working-tree line counts; all three open their handles through `LibGit2`).
7	///
8	/// Why not SwiftGitX (which the rest of `GitProvider` uses)? It cannot express a commit RANGE: its
9	/// `CommitSequence` only calls `git_revwalk_push` and never `git_revwalk_hide`, it surfaces no
10	/// merge-base/graph helper, and it keeps its own `git_repository` pointer `internal` so we can't borrow
11	/// one. "Which of these commits aren't on origin yet" is exactly `HEAD --not <origin tips>`, so we open
12	/// our own handle and ask libgit2 directly. Every handle is freed with `defer`; no pointer escapes.
13	///
14	/// **Semantics.** `origin` only, deliberately: a commit sitting on some other remote (a backup, a fork)
15	/// is not on the project's shared repo, and that's what the badge claims. `nil` from either entry point
16	/// means "couldn't answer" — no origin refs, or a read failed — and the caller must then report
17	/// `.unknown` for EVERY row rather than a partial answer. Skipping one unreadable tip would be worse
18	/// than useless: if that tip was the only one containing a commit, the commit would be badged
19	/// "unpushed" when it isn't.
20	enum GitGraph {
21	  /// What a push-state read was measured against, for tooltip copy. `refName` is set only when origin
22	  /// has exactly one branch, so the UI can name it ("not on origin/main") instead of counting.
23	  struct Scope: Equatable, Sendable {
24	    let refName: String?
25	    let count: Int
26	  }
27	
28	  /// The result of a page read: the commits from `decide` that are NOT reachable from origin, plus the
29	  /// comparison scope.
30	  struct PageRead: Equatable, Sendable {
31	    let unpushed: Set<String>
32	    let scope: Scope
33	  }
34	
35	  /// Which of `decide` are unreachable from any `origin` tip — i.e. `git rev-list HEAD --not
36	  /// <origin tips>` intersected with the page. `nil` ⇒ unanswerable (see the type doc).
37	  ///
38	  /// The walk stops as soon as every id in `decide` has been seen, which is what keeps the pathological
39	  /// case cheap: when NO origin tip intersects local history, hiding removes nothing and the raw walk
40	  /// would enumerate all of history — but then every page commit is unpushed, so they're all found in
41	  /// the first `decide.count` steps and we quit. Ids never yielded before the walk ends are reachable
42	  /// from origin, hence pushed.
43	  static func unpushed(root: URL, decide: Set<String>) -> PageRead? {
44	    LibGit2.withRepository(root) { repo in
45	      guard let tips = originTips(repo), !tips.isEmpty else { return nil }
46	      guard var head = resolve("HEAD", in: repo) else { return nil }
47	
48	      var walk: OpaquePointer?
49	      guard git_revwalk_new(&walk, repo) == 0, let walk else { return nil }
50	      defer { git_revwalk_free(walk) }
51	      guard git_revwalk_push(walk, &head) == 0 else { return nil }
52	      for tip in tips {
53	        var oid = tip.oid
54	        // A tip we can't hide (pruned object, a ref pointing at a non-commit) invalidates the whole
55	        // read — see the type doc on why skipping it would produce a FALSE "unpushed".
56	        guard git_revwalk_hide(walk, &oid) == 0 else { return nil }
57	      }
58	
59	      var found: Set<String> = []
60	      var oid = git_oid()
61	      while found.count < decide.count {
62	        let status = git_revwalk_next(&oid, walk)
63	        if status == GIT_ITEROVER.rawValue { break }
64	        // Any OTHER failure mid-walk (corrupt object in the odb) has to invalidate the read: the ids we
65	        // haven't yielded yet would otherwise be reported "pushed" purely because the walk stopped.
66	        guard status == 0 else { return nil }
67	        let hex = LibGit2.hexString(&oid)
68	        if decide.contains(hex) { found.insert(hex) }
69	      }
70	      return PageRead(unpushed: found, scope: scope(of: tips))
71	    }
72	  }
73	
74	  /// Whether one arbitrary commit is reachable from any `origin` tip — the single-commit form for the
75	  /// changeset detail, where there's no page to bound a walk with. `nil` ⇒ unanswerable.
76	  static func isPushed(root: URL, commitID: String) -> (pushed: Bool, scope: Scope)? {
77	    LibGit2.withRepository(root) { repo in
78	      guard let tips = originTips(repo), !tips.isEmpty else { return nil }
79	      guard var oid = LibGit2.oid(fromHex: commitID) else { return nil }
80	      let oids = tips.map(\.oid)
81	      let status = oids.withUnsafeBufferPointer { buf in
82	        git_graph_reachable_from_any(repo, &oid, buf.baseAddress, buf.count)
83	      }
84	      // 1 = reachable, 0 = not, negative = error (unknown object, corrupt odb) ⇒ unanswerable.
85	      guard status >= 0 else { return nil }
86	      return (status == 1, scope(of: tips))
87	    }
88	  }
89	
90	  // MARK: - Internals
91	
92	  private struct Tip {
93	    let name: String
94	    let oid: git_oid
95	  }
96	
97	  /// Every `refs/remotes/origin/*` tip, resolved to a commit id. `nil` on an iteration failure (damaged
98	  /// refs) — distinct from an empty list (no origin), though both end up `.unknown` at the caller.
99	  ///
100	  /// `refs/remotes/origin/HEAD` is skipped: it's symbolic and resolves to another origin branch already
101	  /// in this list, so it would double a tip and put a meaningless "origin/HEAD" in the tooltip.
102	  private static func originTips(_ repo: OpaquePointer) -> [Tip]? {
103	    // `git_reference_iterator` is a complete type in the headers (unlike the opaque repo/revwalk/ref
104	    // handles), so Swift types it as a concrete pointer rather than `OpaquePointer`.
105	    var iter: UnsafeMutablePointer<git_reference_iterator>?
106	    guard git_reference_iterator_glob_new(&iter, repo, "refs/remotes/origin/*") == 0, let iter
107	    else { return nil }
108	    defer { git_reference_iterator_free(iter) }
109	
110	    var tips: [Tip] = []
111	    var ref: OpaquePointer?
112	    while true {
113	      let status = git_reference_next(&ref, iter)
114	      if status == GIT_ITEROVER.rawValue { break }
115	      guard status == 0, let ref else { return nil }
116	      defer { git_reference_free(ref) }
117	      guard let raw = git_reference_name(ref) else { return nil }
118	      let name = String(cString: raw)
119	      if name == "refs/remotes/origin/HEAD" { continue }
120	      // `name_to_id` resolves symbolic refs, so this is the ref's commit either way.
121	      guard var oid = resolve(name, in: repo) else { return nil }
122	      // The ref resolving is not enough — it can name an object that isn't in the odb (a ref written by
123	      // hand, a pruned pack). `git_revwalk_hide` accepts such an oid without complaint and the walk then
124	      // just ends early, which would silently report unpushed commits as pushed. So prove each tip is a
125	      // real commit up front, and fail the WHOLE read if one isn't.
126	      var commit: OpaquePointer?
127	      guard git_commit_lookup(&commit, repo, &oid) == 0, let commit else { return nil }
128	      git_commit_free(commit)
129	      tips.append(Tip(name: shortName(name), oid: oid))
130	    }
131	    return tips
132	  }
133	
134	  private static func scope(of tips: [Tip]) -> Scope {
135	    Scope(refName: tips.count == 1 ? tips[0].name : nil, count: tips.count)
136	  }
137	
138	  /// `refs/remotes/origin/main` → `origin/main`, the form git itself prints.
139	  private static func shortName(_ fullName: String) -> String {
140	    let prefix = "refs/remotes/"
141	    return fullName.hasPrefix(prefix) ? String(fullName.dropFirst(prefix.count)) : fullName
142	  }
143	
144	  private static func resolve(_ refName: String, in repo: OpaquePointer) -> git_oid? {
145	    var oid = git_oid()
146	    guard git_reference_name_to_id(&oid, repo, refName) == 0 else { return nil }
147	    return oid
148	  }
149	}
